export type Operations = typeof operations;
export type OperationKey = keyof Operations;

type TypeOf<N> = N extends keyof OperationTypes ? OperationTypes[N] : N extends 'text' ? string : N extends 'empty' ? undefined : never;

/** The success body of an operation. */
export type OperationResponse<K extends OperationKey> = TypeOf<Operations[K]['response']['type']>;

/** The request body of an operation (`undefined` when it has none). */
export type OperationRequest<K extends OperationKey> = Operations[K]['request'] extends { readonly type: infer N } ? TypeOf<N> : undefined;

/** The query parameters of an operation (`undefined` when it has none). */
export type OperationQuery<K extends OperationKey> = Operations[K]['query'] extends null ? undefined : TypeOf<Operations[K]['query']>;

/** The path parameters of an operation. */
export type OperationPathParams<K extends OperationKey> = { [P in Operations[K]['pathParams'][number]]: string };

/** The error statuses of an operation. */
export type OperationErrorStatus<K extends OperationKey> = keyof Operations[K]['errors'];

/** The error body of an operation, for one status or for any. */
export type OperationError<K extends OperationKey, S extends OperationErrorStatus<K> = OperationErrorStatus<K>> = Operations[K]['errors'] extends infer E
  ? { [P in keyof E & S]: E[P] extends readonly (infer N)[] ? TypeOf<N> : never }[keyof E & S]
  : never;
